// Shape the Trellis publish payload into YouTube-ready fields.
const b = $json.body || $json;
const m = b.metadata || {};
const chapters = Array.isArray(m.chapters) ? m.chapters : [];
const chapterLines = chapters.map(c => `${c.time || '0:00'} ${c.title || ''}`.trim()).filter(Boolean).join('\n');
const hashtags = Array.isArray(m.hashtags) ? m.hashtags.join(' ') : '';
const rawDescription = String(m.description || '').trim();
function withChapters(description) {
  if (!chapterLines || /(^|\n)Chapters:\n/i.test(description)) return description;
  const contentMatch = description.match(/\n*Content note:/i);
  if (!contentMatch) return [description, 'Chapters:\n' + chapterLines].filter(Boolean).join('\n\n');
  const before = description.slice(0, contentMatch.index).trim();
  const after = description.slice(contentMatch.index).trim();
  return [before, 'Chapters:\n' + chapterLines, after].filter(Boolean).join('\n\n');
}
const descriptionWithChapters = withChapters(rawDescription);
const descParts = [
  descriptionWithChapters,
  hashtags ? '\n\n' + hashtags : '',
];
const description = descParts.join('').trim().slice(0, 4900); // YT desc limit ~5000
const cleanTag = (value) => String(value || '')
  .replace(/^#+/, '')
  .replace(/[,|;]/g, ' ')
  .replace(/[^\w\s-]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 45)
  .trim();
const safeTags = [];
const seen = new Set();
let total = 0;
for (const raw of Array.isArray(m.tags) ? m.tags : []) {
  const tag = cleanTag(raw);
  const key = tag.toLowerCase();
  if (tag.length < 2 || seen.has(key)) continue;
  const nextTotal = total + tag.length + (safeTags.length ? 1 : 0);
  if (safeTags.length >= 15 || nextTotal > 380) break;
  safeTags.push(tag);
  seen.add(key);
  total = nextTotal;
}
const tags = safeTags.join(',');
return { json: {
  publication_id: b.publication_id,
  episode_id: b.episode_id,
  video_url: b.video_url,
  thumbnail_url: b.thumbnail_url || null,
  made_for_kids: b.made_for_kids === true,
  title: (m.title || 'Untitled Episode').slice(0, 95), // YT title max 100
  description,
  tags,
} };

const m = $('Build Metadata').item.json;
const youtubeAccountId = $('Publish Webhook').item.json.body?.youtube_account_id || $('Publish Webhook').item.json.youtube_account_id;
if (!youtubeAccountId) throw new Error('Missing youtube_account_id');
return { json: { ...m, youtube_account_id: youtubeAccountId, category_id: '10', visibility: 'public' }, binary: $binary };

// Pull the YouTube video id out of the upload response regardless of shape
// (top-level id / id.videoId / snippet.resourceId.videoId), with a last-resort
// scan for an 11-char YouTube-id-shaped token.
const y = $json || {};
let id = (y.id && typeof y.id === 'object') ? y.id.videoId : y.id;
id = id || y?.snippet?.resourceId?.videoId || y.videoId;
if (!id) { const m = JSON.stringify(y).match(/"([A-Za-z0-9_-]{11})"/); id = m ? m[1] : null; }
return { json: { video_id: id, youtube_url: id ? ('https://youtu.be/' + id) : null } };
